package com.fieldcrm.android.ui.roles.creditanalyst.dashboard
import androidx.compose.runtime.Composable
import com.fieldcrm.android.data.api.DashboardMetrics
import com.fieldcrm.android.ui.roles.shared.*
import com.fieldcrm.android.ui.viewmodel.Screen
@Composable fun CreditAnalystDashboard(userName: String, metrics:DashboardMetrics?,loading:Boolean,error:String?,onOpen:(Screen)->Unit,onNavigateToSettings:()->Unit){val data=metrics?.data;val m=data?.metrics;WorkspaceDashboardPage("Credit Analyst","Assess affordability, bureau evidence, OCR exceptions, and credit risk.",userName,"Credit Analyst",listOf(WorkspaceMetric("Assessments due",m?.reviews_due?.toString()?:"Not available"),WorkspaceMetric("OCR exceptions",m?.ocr_exceptions?.toString()?:"Not available"),WorkspaceMetric("Reviewed today",m?.reviewed_today?.toString()?:"Not available")),listOf(WorkspaceAction("Credit Assessments",Screen.CreditReviewQueue,data?.reviews.orEmpty().reviewWorkspaceLines()),WorkspaceAction("OCR Exceptions",Screen.OcrExceptions,data?.exceptions.orEmpty().exceptionWorkspaceLines()),WorkspaceAction("Search Credit Dossiers",Screen.SearchResults,data?.reviews.orEmpty().reviewWorkspaceLines())),loading,error,onOpen,onNavigateToSettings)}
